script:
export const meta = {
  name: 'count-and-sum',
  description: 'Two agents answer 2+2 and 3+3, then one agent adds the answers',
  phases: [{ title: 'Count' }, { title: 'Sum' }],
}

const ANSWER = {
  type: 'object',
  properties: { answer: { type: 'string' } },
  required: ['answer'],
}

phase('Count')
const [a, b] = await parallel([
  () => agent('What is 2+2? Reply with one word only.', { label: 'count:2+2', phase: 'Count', schema: ANSWER }),
  () => agent('What is 3+3? Reply with one word only.', { label: 'count:3+3', phase: 'Count', schema: ANSWER }),
])

phase('Sum')
const total = await agent(
  `Add these two numbers and reply with the result as one word: ${a?.answer} and ${b?.answer}.`,
  { label: 'sum', phase: 'Sum', schema: ANSWER },
)

return { first: a?.answer, second: b?.answer, sum: total?.answer }
